import { NextResponse, type NextRequest } from "next/server"
import { locales, defaultLocale } from "@/lib/i18n/config"

function getLocale(request: NextRequest): string {
  const cookieLocale = request.cookies.get("NEXT_LOCALE")?.value
  if (cookieLocale && (locales as readonly string[]).includes(cookieLocale)) {
    return cookieLocale
  }

  const acceptLang = request.headers.get("accept-language")
  if (acceptLang) {
    const preferred = acceptLang
      .split(",")
      .map((part) => part.split(";")[0].trim().toLowerCase().split("-")[0])

    for (const lang of preferred) {
      if ((locales as readonly string[]).includes(lang)) {
        return lang
      }
    }
  }

  return defaultLocale
}

export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl

  if (
    pathname.startsWith("/_next") ||
    pathname.startsWith("/api") ||
    pathname.includes(".") ||
    pathname === "/robots.txt" ||
    pathname === "/sitemap.xml"
  ) {
    return NextResponse.next()
  }

  const pathnameHasLocale = locales.some(
    (locale) => pathname === `/${locale}` || pathname.startsWith(`/${locale}/`),
  )

  if (pathnameHasLocale) return NextResponse.next()

  const locale = getLocale(request)
  const url = request.nextUrl.clone()
  url.pathname = `/${locale}${pathname === "/" ? "" : pathname}`

  const response = NextResponse.redirect(url)
  response.cookies.set("NEXT_LOCALE", locale, { maxAge: 60 * 60 * 24 * 365, path: "/" })
  return response
}

export const config = {
  matcher: ["/((?!_next|api|.*\\..*).*)"],
}

const locales = ["fr", "en", "de", "it"] as const;
type Locale = (typeof locales)[number];
const ogLocales: Record<Locale, string> = {
  fr: "fr_CH",
  en: "en_US",
  de: "de_CH",
  it: "it_CH",
};

/**
 * Framework-agnostic metadata shape (structurally compatible with
 * Next.js `Metadata`). Sites adapt it to their framework:
 *   - Next.js  : `return buildMetadata(...) as Metadata`
 *   - TanStack : feed the fields into the route `head` meta tags
 */
export interface SiteMetadata {
  title?: string
  description?: string
  alternates?: {
    canonical?: string
    languages?: Record<string, string>
  }
  robots?: { index: boolean; follow: boolean } | string
  openGraph?: {
    title?: string
    description?: string
    url?: string
    siteName?: string
    locale?: string
    type?: string
    images?: { url: string; width?: number; height?: number; alt?: string }[]
  }
  twitter?: {
    card?: string
    title?: string
    description?: string
    images?: string[]
  }
}

interface BuildMetadataOptions {
  locale: Locale
  title: string
  description: string
  path: string
  siteUrl: string
  siteName: string
  ogImage?: string
  noIndex?: boolean
}

export function buildMetadata({
  locale,
  title,
  description,
  path,
  siteUrl,
  siteName,
  ogImage,
  noIndex = false,
}: BuildMetadataOptions): SiteMetadata {
  const cleanPath = path === "/" ? "" : path
  const canonical = `${siteUrl}/${locale}${cleanPath}`
  const ogImageUrl = ogImage ?? `${siteUrl}/images/hero.webp`

  const languages: Record<string, string> = {}
  for (const l of locales) {
    languages[l] = `${siteUrl}/${l}${cleanPath}`
  }
  languages["x-default"] = `${siteUrl}/${locales[0]}${cleanPath}`

  return {
    title,
    description,
    alternates: { canonical, languages },
    robots: noIndex ? { index: false, follow: true } : undefined,
    openGraph: {
      title,
      description,
      url: canonical,
      siteName,
      locale: ogLocales[locale],
      type: "website",
      images: [{ url: ogImageUrl, width: 1200, height: 630, alt: siteName }],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [ogImageUrl],
    },
  }
}

interface JsonLdProps {
  data: Record<string, unknown>
}

export function JsonLd({ data }: JsonLdProps) {
  return (
    <script
      type="application/ld+json"
      dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }}
    />
  )
}

export function organizationJsonLd({
  name,
  url,
  logo,
  phone,
  email,
  address,
}: {
  name: string
  url: string
  logo?: string
  phone?: string
  email?: string
  address?: { street: string; city: string; postalCode: string; country: string }
}) {
  return {
    "@context": "https://schema.org",
    "@type": "LocalBusiness",
    "@id": `${url}/#organization`,
    name,
    url,
    ...(logo && { logo }),
    ...(phone && { telephone: phone }),
    ...(email && { email }),
    ...(address && {
      address: {
        "@type": "PostalAddress",
        streetAddress: address.street,
        addressLocality: address.city,
        postalCode: address.postalCode,
        addressCountry: address.country,
      },
    }),
  }
}

export function breadcrumbJsonLd(items: { name: string; url: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: item.name,
      item: item.url,
    })),
  }
}

export function faqJsonLd(items: { question: string; answer: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: items.map((item) => ({
      "@type": "Question",
      name: item.question,
      acceptedAnswer: { "@type": "Answer", text: item.answer },
    })),
  }
}

export function serviceJsonLd({
  name,
  description,
  provider,
  url,
}: {
  name: string
  description: string
  provider: { name: string; url: string }
  url: string
}) {
  return {
    "@context": "https://schema.org",
    "@type": "Service",
    name,
    description,
    url,
    provider: {
      "@type": "LocalBusiness",
      name: provider.name,
      url: provider.url,
    },
  }
}

"use client"

import { Accordion as AccordionPrimitive } from "@base-ui/react/accordion";
import { ChevronDownIcon } from "lucide-react";
import * as React from "react";

import { cn } from "#/lib/utils";

type AccordionValue = string;

interface AccordionProps extends Omit<
  AccordionPrimitive.Root.Props,
  "value" | "defaultValue" | "onValueChange" | "multiple"
> {
  type?: "single" | "multiple";
  value?: AccordionValue | AccordionValue[];
  defaultValue?: AccordionValue | AccordionValue[];
  onValueChange?: (value: AccordionValue | AccordionValue[]) => void;
}

function Accordion({
  type = "single",
  value,
  defaultValue,
  onValueChange,
  className,
  ...props
}: AccordionProps) {
  const multiple = type === "multiple";

  return (
    <AccordionPrimitive.Root
      data-slot="accordion"
      className={cn("w-full", className)}
      multiple={multiple}
      value={value === undefined ? undefined : Array.isArray(value) ? value : [value]}
      defaultValue={
        defaultValue === undefined
          ? undefined
          : Array.isArray(defaultValue)
            ? defaultValue
            : [defaultValue]
      }
      onValueChange={(v) => onValueChange?.(multiple ? v : (v[0] ?? undefined))}
      {...props}
    />
  );
}

function AccordionItem({ className, value, ...props }: AccordionPrimitive.Item.Props) {
  return (
    <AccordionPrimitive.Item
      data-slot="accordion-item"
      className={cn("border-b last:border-b-0", className)}
      value={value}
      {...props}
    />
  );
}

function AccordionTrigger({ className, children, ...props }: AccordionPrimitive.Trigger.Props) {
  return (
    <AccordionPrimitive.Header className="flex">
      <AccordionPrimitive.Trigger
        data-slot="accordion-trigger"
        className={cn(
          "flex flex-1 items-start justify-between gap-4 rounded-md py-4 text-left text-sm font-medium transition-all outline-none hover:underline focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 [&[data-panel-open]>svg]:rotate-180",
          className,
        )}
        {...props}
      >
        {children}
        <ChevronDownIcon className="pointer-events-none size-4 shrink-0 translate-y-0.5 text-muted-foreground transition-transform duration-200" />
      </AccordionPrimitive.Trigger>
    </AccordionPrimitive.Header>
  );
}

// The expand/collapse animation uses height keyframes (see ./accordion.css)
// driven by base-ui's measured --accordion-panel-height variable. Keyframes
// play from a painted start on every open, so the first open animates even
// though closed panels are unmounted (base-ui keeps them mounted during the
// exit animation and unmounts after animationend).
import "./accordion.css";

function AccordionContent({ className, children, ...props }: AccordionPrimitive.Panel.Props) {
  return (
    <AccordionPrimitive.Panel
      data-slot="accordion-content"
      className={cn(
        "overflow-hidden text-sm data-open:animate-[accordion-down_0.2s_ease-out] data-closed:animate-[accordion-up_0.2s_ease-out]",
        className,
      )}
      {...props}
    >
      <div className="h-(--accordion-panel-height) pt-0 pb-4">{children}</div>
    </AccordionPrimitive.Panel>
  );
}

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };

/* Accordion expand/collapse keyframes.
   base-ui measures the panel height and exposes it as the inline CSS variable
   --accordion-panel-height (pixels) on the panel element, so the keyframes can
   animate height between 0 and the measured value. This is the same animation
   base-ui's own docs recommend; the classes are referenced by the accordion
   component as arbitrary animate utilities (data-open / data-closed hooks). */
@keyframes accordion-down {
  from {
    height: 0;
  }
  to {
    height: var(--accordion-panel-height, auto);
  }
}

@keyframes accordion-up {
  from {
    height: var(--accordion-panel-height, auto);
  }
  to {
    height: 0;
  }
}

"use client"

import { motion, type Variants } from "motion/react"
import { useSyncExternalStore } from "react"
import type { ReactNode } from "react"
import { cn } from "#/lib/utils"

const emptySubscribe = () => () => {}

function useHydrated() {
  return useSyncExternalStore(
    emptySubscribe,
    () => true,
    () => false,
  )
}

const fadeUp: Variants = {
  hidden: { opacity: 0, y: 20 },
  visible: { opacity: 1, y: 0 },
}

const fadeIn: Variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1 },
}

const scaleIn: Variants = {
  hidden: { opacity: 0, scale: 0.95 },
  visible: { opacity: 1, scale: 1 },
}

export interface AnimationProps {
  children: ReactNode
  delay?: number
  className?: string
}

export function FadeUp({ children, delay = 0, className }: AnimationProps) {
  const hydrated = useHydrated()
  return (
    <motion.div
      initial={hydrated ? "hidden" : false}
      whileInView="visible"
      viewport={{ once: true, margin: "-50px" }}
      variants={fadeUp}
      transition={{ duration: 0.5, delay, ease: "easeOut" }}
      className={cn(className)}
    >
      {children}
    </motion.div>
  )
}

export function FadeIn({ children, delay = 0, className }: AnimationProps) {
  const hydrated = useHydrated()
  return (
    <motion.div
      initial={hydrated ? "hidden" : false}
      whileInView="visible"
