// Framework-agnostic Link shim.
// Each site provides the implementation for its framework:
//   - Next.js   : re-export of `next/link`
//   - TanStack  : re-export of `@tanstack/react-router`'s Link (typed `to`)
// The registry imports this shim and never imports a framework router directly.

import { forwardRef } from "react"

import { cn } from "#/lib/utils"

export interface LinkProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  href: string
  children?: React.ReactNode
}

/**
 * Minimal anchor-based Link. Sites that need router-aware navigation
 * (prefetch, active states) replace this file with a framework re-export —
 * the props above keep the component contract stable.
 */
export const Link = forwardRef<HTMLAnchorElement, LinkProps>(function Link(
  { href, className, children, ...props },
  ref,
) {
  return (
    <a href={href} ref={ref} className={cn(className)} {...props}>
      {children}
    </a>
  )
})

// Framework-agnostic Image shim.
// Each site provides the implementation for its framework:
//   - Next.js  : re-export of `next/image`
//   - TanStack : plain <img> (or the site's image component)
// The registry imports this shim and never imports a framework image component.
//
// Next-specific props (fill, priority, sizes, quality) are translated to
// plain <img> equivalents so components keep working everywhere.

import { cn } from "#/lib/utils"

export interface ImageProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  src: string
  alt: string
  width?: number
  height?: number
  unoptimized?: boolean
  /** Fill the parent (absolute inset-0) — next/image compatible. */
  fill?: boolean
  /** Load eagerly with high fetch priority — next/image compatible. */
  priority?: boolean
  sizes?: string
  quality?: number
}

/**
 * Plain <img> based Image. Sites that need an image optimizer replace
 * this file with a framework component — the props above keep the
 * component contract stable.
 */
export function Image({
  src,
  alt,
  width,
  height,
  unoptimized,
  fill,
  priority,
  sizes,
  quality,
  loading,
  className,
  ...props
}: ImageProps) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- framework-agnostic shim
    <img
      src={src}
      alt={alt}
      width={fill ? undefined : width}
      height={fill ? undefined : height}
      sizes={sizes}
      loading={loading ?? (priority ? "eager" : "lazy")}
      fetchPriority={priority ? "high" : undefined}
      data-quality={quality}
      data-unoptimized={unoptimized || undefined}
      className={cn(fill && "absolute inset-0 h-full w-full", className)}
      {...props}
    />
  )
}

// Framework-agnostic Script shim (inline script injection).
// Each site provides the implementation for its framework:
//   - Next.js  : re-export of `next/script` (supports `strategy` props)
//   - TanStack : renders the script in the route `head` (or plain <script>)
// The registry imports this shim and never imports a framework script API.

export interface ScriptProps extends React.ScriptHTMLAttributes<HTMLScriptElement> {
  id?: string
  /** Framework hint — Next.js uses strategies; other frameworks ignore it. */
  strategy?: "afterInteractive" | "beforeInteractive" | "lazyOnload"
  /** Inline script source (JS string). */
  code?: string
  children?: string
}

/**
 * Minimal inline <script>. Sites that need framework script handling
 * (e.g. Next.js `beforeInteractive`) replace this file with a framework
 * component — the props above keep the component contract stable.
 */
export function Script({ id, strategy, code, children, ...props }: ScriptProps) {
  const source = code ?? children ?? ""
  return <script id={id} data-strategy={strategy} dangerouslySetInnerHTML={{ __html: source }} {...props} />
}

"use client"

// Framework-agnostic pathname hook (replaces `usePathname` from next/navigation).
// Each site provides the implementation for its framework:
//   - Next.js  : re-export of `next/navigation`'s usePathname
//   - TanStack : re-export of `@tanstack/react-router`'s useLocation().pathname

import { useSyncExternalStore } from "react"

function subscribe() {
  return () => {}
}

/**
 * Minimal pathname getter for environments without a router hook.
 * Sites with a real router replace this file with a framework re-export.
 */
export function usePathname(): string {
  return useSyncExternalStore(
    subscribe,
    () => (typeof window === "undefined" ? "" : window.location.pathname),
    () => "",
  )
}

"use client";

import * as React from "react";

import { cn } from "#/lib/utils";

export type NewsletterProps = Omit<React.ComponentPropsWithoutRef<"section">, "onSubmit"> & {
  title?: string;
  description?: string;
  eyebrow?: string;
  placeholder?: string;
  buttonLabel?: string;
  privacyText?: string;
  loading?: boolean;
  successMessage?: string;
  errorMessage?: string;
  disabled?: boolean;
  icon?: React.ReactNode;
  validationErrorMessage?: string;
  submitErrorMessage?: string;
  emailLabel?: string;
  loadingLabel?: string;
  onSubmit: (email: string) => void | Promise<void>;
};

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function Newsletter({
  title = "Stay in the loop",
  description = "Get product updates and practical tips delivered to your inbox.",
  eyebrow,
  placeholder = "you@example.com",
  buttonLabel = "Subscribe",
  privacyText,
  loading = false,
  successMessage,
  errorMessage,
  disabled = false,
  icon,
  validationErrorMessage = "Please enter a valid email address.",
  submitErrorMessage = "Something went wrong. Please try again.",
  emailLabel = "Email address",
  loadingLabel = "Submitting...",
  onSubmit,
  className,
  ...props
}: NewsletterProps) {
  const baseId = React.useId();
  const inputId = `${baseId}-email`;
  const helperId = `${baseId}-helper`;
  const errorId = `${baseId}-error`;
  const successId = `${baseId}-success`;

  const [email, setEmail] = React.useState("");
  const [validationError, setValidationError] = React.useState<string>();
  const [submitError, setSubmitError] = React.useState<string>();
  const [showStatus, setShowStatus] = React.useState(true);
  const [submitting, setSubmitting] = React.useState(false);

  const hasError = Boolean(validationError || submitError || (showStatus && errorMessage));
  const inlineError = validationError || submitError || (showStatus ? errorMessage : undefined);
  const inlineSuccess = !inlineError && showStatus ? successMessage : undefined;
  const isLoading = loading || submitting;
  const isDisabled = disabled || isLoading;

  const describedBy = [privacyText ? helperId : undefined, inlineError ? errorId : undefined]
    .filter(Boolean)
    .join(" ");

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (isDisabled) {
      return;
    }

    const normalizedEmail = email.trim();

    if (!EMAIL_REGEX.test(normalizedEmail)) {
      setShowStatus(false);
      setValidationError(validationErrorMessage);
      return;
    }

    setShowStatus(true);
    setValidationError(undefined);
    setSubmitError(undefined);

    try {
      setSubmitting(true);
      await Promise.resolve(onSubmit(normalizedEmail));
    } catch {
      setSubmitError(submitErrorMessage);
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <section
      className={cn(
        "w-full rounded-xl border border-border bg-background p-5 shadow-sm sm:p-6",
        className,
      )}
      {...props}
    >
      <div className="space-y-2">
        {eyebrow ? (
          <p className="font-eyebrow text-xs font-semibold uppercase tracking-[0.14em] text-primary">
            {eyebrow}
          </p>
        ) : null}
        <div className="flex items-center gap-2">
          {icon ? <span className="text-muted-foreground">{icon}</span> : null}
          <h2 className="text-lg font-semibold text-foreground">{title}</h2>
        </div>
        <p className="text-sm text-muted-foreground">{description}</p>
      </div>

      <form className="mt-4" onSubmit={handleSubmit} noValidate>
        <label className="sr-only" htmlFor={inputId}>
          {emailLabel}
        </label>
        <div className="flex flex-col gap-3 sm:flex-row">
          <input
            id={inputId}
            type="email"
            name="email"
            autoComplete="email"
            value={email}
            onChange={(event) => {
              setEmail(event.target.value);
              setValidationError(undefined);
              setSubmitError(undefined);
              setShowStatus(false);
            }}
            placeholder={placeholder}
            disabled={isDisabled}
            aria-invalid={hasError}
            aria-describedby={describedBy || undefined}
            className="h-11 w-full rounded-md border border-border bg-background px-3 text-sm text-foreground placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-60"
          />
          <button
            type="submit"
            disabled={isDisabled}
            className="inline-flex h-11 shrink-0 items-center justify-center rounded-md bg-primary px-4 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-60"
          >
            {isLoading ? loadingLabel : buttonLabel}
          </button>
        </div>

        {privacyText ? (
          <p className="mt-3 text-xs text-muted-foreground" id={helperId}>
            {privacyText}
          </p>
        ) : null}

        {inlineError ? (
          <p className="mt-2 text-sm text-red-600 dark:text-red-400" id={errorId} role="alert" aria-live="assertive">
            {inlineError}
          </p>
        ) : null}

        {inlineSuccess ? (
          <p className="mt-2 text-sm text-emerald-700 dark:text-emerald-400" id={successId} role="status" aria-live="polite">
            {inlineSuccess}
          </p>
        ) : null}
      </form>
    </section>
  );
}

