"use client"

import { useEffect, useState, useCallback } from "react"
import { cn } from "#/lib/utils"

declare global {
  interface Window {
    gtag?: (...args: unknown[]) => void
    dataLayer?: object[]
  }
}

export interface ConsentState {
  necessary: boolean
  analytics: boolean
  marketing: boolean
}

const DEFAULT_CONSENT: ConsentState = {
  necessary: true,
  analytics: false,
  marketing: false,
}

function ensureGtag() {
  if (typeof window === "undefined") return
  window.gtag =
    window.gtag ||
    ((...args: unknown[]) => {
      window.dataLayer = window.dataLayer || []
      window.dataLayer.push(args)
    })
}

function serialize(state: ConsentState): string {
  return JSON.stringify(state)
}

function deserialize(raw: string): ConsentState | null {
  try {
    const parsed = JSON.parse(raw)
    if (
      typeof parsed === "object" &&
      parsed !== null &&
      typeof parsed.necessary === "boolean" &&
      typeof parsed.analytics === "boolean" &&
      typeof parsed.marketing === "boolean"
    ) {
      return parsed as ConsentState
    }
    return null
  } catch {
    return null
  }
}

function applyConsent(state: ConsentState) {
  ensureGtag()
  window.gtag?.("consent", "update", {
    ad_storage: state.marketing ? "granted" : "denied",
    analytics_storage: state.analytics ? "granted" : "denied",
    ad_user_data: state.marketing ? "granted" : "denied",
    ad_personalization: state.marketing ? "granted" : "denied",
  })
}

export interface CookieBannerProps {
  consentKey?: string
  manageEvent?: string
  text: string
  acceptAllLabel: string
  acceptSelectionLabel: string
  rejectLabel: string
  policyLabel: string
  privacyHref: string
  necessaryTitle: string
  necessaryDescription: string
  analyticsTitle: string
  analyticsDescription: string
  marketingTitle: string
  marketingDescription: string
  dialogLabel?: string
  showAnalytics?: boolean
  showMarketing?: boolean
  hidden?: boolean
}

export function CookieBanner({
  consentKey = "cookie-consent",
  manageEvent = "manage-cookies",
  text,
  acceptAllLabel,
  acceptSelectionLabel,
  rejectLabel,
  policyLabel,
  privacyHref,
  necessaryTitle,
  necessaryDescription,
  analyticsTitle,
  analyticsDescription,
  marketingTitle,
  marketingDescription,
  dialogLabel = "Cookies",
  showAnalytics = true,
  showMarketing = false,
  hidden = false,
}: CookieBannerProps) {
  const [visible, setVisible] = useState(false)
  const [draft, setDraft] = useState<ConsentState>(DEFAULT_CONSENT)

  const evaluate = useCallback(() => {
    const stored = localStorage.getItem(consentKey)
    if (stored) {
      const parsed = deserialize(stored)
      if (parsed) {
        applyConsent(parsed)
        setDraft(parsed)
        setVisible(false)
        return
      }
    }
    applyConsent(DEFAULT_CONSENT)
    setDraft(DEFAULT_CONSENT)
    setVisible(true)
  }, [consentKey])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- lit le consent stocké (setState d'hydratation)
    evaluate()
    const onStorage = (e: StorageEvent) => {
      if (e.key === consentKey) evaluate()
    }
    const onManage = () => {
      const stored = localStorage.getItem(consentKey)
      setDraft(stored ? (deserialize(stored) ?? DEFAULT_CONSENT) : DEFAULT_CONSENT)
      setVisible(true)
    }
    window.addEventListener("storage", onStorage)
    window.addEventListener(manageEvent, onManage)
    return () => {
      window.removeEventListener("storage", onStorage)
      window.removeEventListener(manageEvent, onManage)
    }
  }, [evaluate, consentKey, manageEvent])

  const acceptAll = () => {
    const state: ConsentState = { necessary: true, analytics: true, marketing: true }
    localStorage.setItem(consentKey, serialize(state))
    applyConsent(state)
    setVisible(false)
  }

  const rejectAll = () => {
    const state: ConsentState = { necessary: true, analytics: false, marketing: false }
    localStorage.setItem(consentKey, serialize(state))
    applyConsent(state)
    setVisible(false)
  }

  const acceptSelection = () => {
    localStorage.setItem(consentKey, serialize(draft))
    applyConsent(draft)
    setVisible(false)
  }

  if (hidden || !visible) return null

  return (
    <div
      role="dialog"
      aria-label={dialogLabel}
      aria-live="polite"
      className={cn(
        "fixed inset-x-0 bottom-0 z-[60] p-4 sm:p-6",
        "animate-in slide-in-from-bottom-4 fade-in duration-300",
      )}
    >
      <div className="container-premium">
        <div className="flex flex-col gap-4 rounded-xl border border-border bg-background p-5 shadow-lg">
          <p className="max-w-2xl text-sm leading-relaxed text-foreground">
            {text}{" "}
            <a
              href={privacyHref}
              className="font-semibold text-primary underline underline-offset-2"
            >
              {policyLabel}
            </a>
          </p>

          <div className="space-y-3">
            <label className="flex cursor-not-allowed items-start gap-3 opacity-70">
                <input
                  type="checkbox"
                  checked
                  disabled
                  className="mt-0.5 h-4 w-4 shrink-0 rounded accent-primary"
                />
                <div>
                  <p className="text-sm font-semibold text-foreground">
                    {necessaryTitle}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {necessaryDescription}
                  </p>
                </div>
              </label>

              {showAnalytics && (
                <label className="flex cursor-pointer items-start gap-3">
                  <input
                    type="checkbox"
                    checked={draft.analytics}
                    onChange={(e) =>
                      setDraft((prev) => ({
                        ...prev,
                        analytics: e.target.checked,
                      }))
                    }
                    className="mt-0.5 h-4 w-4 shrink-0 rounded accent-primary"
                  />
                  <div>
                    <p className="text-sm font-semibold text-foreground">
                      {analyticsTitle}
                    </p>
                    <p className="text-xs text-muted-foreground">
                      {analyticsDescription}
                    </p>
                  </div>
                </label>
              )}

              {showMarketing && (
                <label className="flex cursor-pointer items-start gap-3">
                  <input
                    type="checkbox"
                    checked={draft.marketing}
                    onChange={(e) =>
                      setDraft((prev) => ({
                        ...prev,
                        marketing: e.target.checked,
                      }))
                    }
                    className="mt-0.5 h-4 w-4 shrink-0 rounded accent-primary"
                  />
                  <div>
                    <p className="text-sm font-semibold text-foreground">
                      {marketingTitle}
                    </p>
                    <p className="text-xs text-muted-foreground">
                      {marketingDescription}
                    </p>
                  </div>
                </label>
              )}
            </div>

          <div className="flex flex-wrap gap-3">
            <button
              type="button"
              onClick={acceptAll}
              className="inline-flex h-10 items-center justify-center rounded-lg bg-primary px-4 text-sm font-semibold text-primary-foreground outline-none transition-colors hover:bg-primary/90 focus-visible:ring-3 focus-visible:ring-primary/40"
            >
              {acceptAllLabel}
            </button>
            <button
              type="button"
              onClick={acceptSelection}
              className="inline-flex h-10 items-center justify-center rounded-lg border border-border bg-background px-4 text-sm font-semibold text-foreground outline-none transition-colors hover:bg-muted focus-visible:ring-3 focus-visible:ring-ring/40"
            >
              {acceptSelectionLabel}
            </button>
            <button
              type="button"
              onClick={rejectAll}
              className="inline-flex h-10 items-center justify-center rounded-lg border border-border bg-background px-4 text-sm font-semibold text-foreground outline-none transition-colors hover:bg-muted focus-visible:ring-3 focus-visible:ring-ring/40"
            >
              {rejectLabel}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

"use client"

import { Link } from "#/components/ui/link"
import { usePathname } from "#/components/ui/use-location"
import { Globe, Check } from "lucide-react"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "#/components/ui/dropdown-menu"
import { cn } from "#/lib/utils"

export interface LanguageSwitcherProps {
  locale: string
  locales: string[]
  localeNames: Record<string, string>
  localeShort: Record<string, string>
  ariaLabel?: string
  className?: string
}

export function LanguageSwitcher({
  locale,
  locales,
  localeNames,
  localeShort,
  ariaLabel = "Language",
  className,
}: LanguageSwitcherProps) {
  const pathname = usePathname()
  const pathnameWithoutLocale =
    pathname.replace(new RegExp(`^/(${locales.join("|")})`), "") || ""

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        aria-label={ariaLabel}
        className={cn(
          "inline-flex items-center gap-1 rounded-md px-2.5 py-2 text-sm font-medium text-foreground/80 outline-none transition-colors hover:text-primary focus-visible:ring-2 focus-visible:ring-ring",
          className,
        )}
      >
        <Globe className="h-4 w-4" aria-hidden="true" />
        <span>{localeShort[locale] ?? locale.toUpperCase()}</span>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-40">
        {locales.map((l) => (
          <DropdownMenuItem key={l} asChild className="justify-between">
            <Link href={`/${l}${pathnameWithoutLocale}`}>
              {localeNames[l] ?? l}
              {l === locale && (
                <Check className="h-4 w-4 text-primary" aria-hidden="true" />
              )}
            </Link>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

