"use client"

import { useState, useEffect } from "react"
import { Link } from "#/components/ui/link"
import { usePathname } from "#/components/ui/use-location"
import { Menu, X, ChevronDown } from "lucide-react"
import { Sheet, SheetContent, SheetTrigger, SheetTitle } from "#/components/ui/sheet"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "#/components/ui/dropdown-menu"
import { CtaExternal } from "#/components/ui/cta-button"
import { LanguageSwitcher } from "#/components/navigation/language-switcher"
import { cn } from "#/lib/utils"

export interface NavItem {
  label: string
  href: string
  children?: NavItem[]
}

export interface NavbarProps {
  logo: { src?: string; alt: string; href: string; initial?: string }
  items: NavItem[]
  cta: { label: string; href: string }
  /** Optional login link (auth enabled) - desktop beside CTA, mobile below it. */
  loginHref?: string
  loginLabel?: string
  locale: string
  locales: string[]
  localeNames: Record<string, string>
  localeShort: Record<string, string>
  siteName: string
  menuLabel?: string
  languageLabel?: string
  closeLabel?: string
  navLabel?: string
  mobileNavLabel?: string
  controls?: React.ReactNode
}

export function Navbar({
  logo,
  items,
  cta,
  loginHref,
  loginLabel,
  locale,
  locales,
  localeNames,
  localeShort,
  siteName,
  menuLabel = "Menu",
  languageLabel = "Language",
  closeLabel = "Close",
  navLabel = "Main navigation",
  mobileNavLabel = "Mobile navigation",
  controls,
}: NavbarProps) {
  const pathname = usePathname()
  const [scrolled, setScrolled] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 8)
    onScroll()
    window.addEventListener("scroll", onScroll, { passive: true })
    return () => window.removeEventListener("scroll", onScroll)
  }, [])

  const isActive = (href: string) => {
    if (href === `/${locale}`) return pathname === `/${locale}`
    return pathname.startsWith(href)
  }

  return (
    <header
      className={cn(
        "sticky top-0 z-50 w-full border-b transition-colors",
        scrolled
          ? "border-border bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/80"
          : "border-transparent bg-background",
      )}
    >
      <div className="container-premium flex h-16 items-center justify-between gap-4 lg:h-20">
        <Link
          href={logo.href}
          className="flex items-center gap-2 rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          {logo.src ? (
            <img src={logo.src} alt={logo.alt} className="h-9 w-auto" />
          ) : (
            <span className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary text-sm font-bold text-primary-foreground">
              {logo.initial ?? siteName.charAt(0)}
            </span>
          )}
          <span className="text-lg font-bold tracking-tight text-foreground">
            {siteName}
          </span>
        </Link>

        <nav className="hidden items-center gap-1 lg:flex" aria-label={navLabel}>
          {items.map((item) =>
            item.children && item.children.length > 0 ? (
              <DropdownMenu key={item.href}>
                <DropdownMenuTrigger
                  className={cn(
                    "inline-flex items-center gap-1 rounded-full px-4 py-2 text-sm font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring",
                    isActive(item.href)
                      ? "bg-primary text-primary-foreground"
                      : "text-foreground hover:bg-secondary",
                  )}
                >
                  {item.label}
                  <ChevronDown className="h-4 w-4" aria-hidden="true" />
                </DropdownMenuTrigger>
                <DropdownMenuContent align="start" className="w-56">
                  {item.children.map((child) => (
                    <DropdownMenuItem key={child.href} asChild>
                      <Link href={child.href}>{child.label}</Link>
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>
            ) : (
              <Link
                key={item.href}
                href={item.href}
                className={cn(
                  "rounded-full px-4 py-2 text-sm font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring",
                  isActive(item.href)
                    ? "bg-primary text-primary-foreground"
                    : "text-foreground hover:bg-secondary",
                )}
                aria-current={isActive(item.href) ? "page" : undefined}
              >
                {item.label}
              </Link>
            ),
          )}
        </nav>

        <div className="flex items-center gap-2">
          {controls}

          <LanguageSwitcher
            locale={locale}
            locales={locales}
            localeNames={localeNames}
            localeShort={localeShort}
            ariaLabel={languageLabel}
          />

          <CtaExternal href={cta.href} className="hidden md:inline-flex">
            {cta.label}
          </CtaExternal>

          {loginHref && (
            <Link
              href={loginHref}
              className="hidden border-l border-border pl-3 text-sm font-medium text-foreground/70 transition-colors hover:text-primary md:inline-flex"
            >
              {loginLabel}
            </Link>
          )}

          <Sheet open={mobileOpen} onOpenChange={setMobileOpen}>
            <SheetTrigger
              aria-label={menuLabel}
              className="inline-flex h-10 w-10 items-center justify-center rounded-md text-foreground outline-none transition-colors hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring lg:hidden"
            >
              <Menu className="h-5 w-5" aria-hidden="true" />
            </SheetTrigger>
            <SheetContent side="right" showCloseButton={false} className="w-full max-w-sm p-0">
              <SheetTitle className="sr-only">{menuLabel}</SheetTitle>
              <div className="flex items-center justify-between border-b border-border px-5 py-4">
                <span className="text-lg font-bold text-foreground">{siteName}</span>
                <button
                  type="button"
                  onClick={() => setMobileOpen(false)}
                  aria-label={closeLabel}
                  className="inline-flex h-9 w-9 items-center justify-center rounded-md text-foreground hover:bg-muted"
                >
                  <X className="h-5 w-5" aria-hidden="true" />
                </button>
              </div>
              <nav className="flex max-h-[calc(100dvh-4rem)] flex-col gap-1 overflow-y-auto px-5 py-6" aria-label={mobileNavLabel}>
                {items.map((item) => (
                  <div key={item.href}>
                    <Link
                      href={item.href}
                      onClick={() => setMobileOpen(false)}
                      className="block rounded-2xl px-4 py-3 font-medium outline-none transition-colors hover:bg-secondary focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      {item.label}
                    </Link>
                    {item.children?.map((child) => (
                      <Link
                        key={child.href}
                        href={child.href}
                        onClick={() => setMobileOpen(false)}
                        className="block rounded-2xl py-3 pl-8 pr-4 text-sm font-medium text-foreground/80 outline-none transition-colors hover:bg-secondary focus-visible:ring-2 focus-visible:ring-ring"
                      >
                        {child.label}
                      </Link>
                    ))}
                  </div>
                ))}
                <CtaExternal href={cta.href} size="lg" className="mt-4 w-full">
                  {cta.label}
                </CtaExternal>
                {loginHref && (
                  <Link
                    href={loginHref}
                    onClick={() => setMobileOpen(false)}
                    className="mt-4 block border-t border-border pt-4 text-center text-sm font-medium text-muted-foreground transition-colors hover:text-primary"
                  >
                    {loginLabel}
                  </Link>
                )}
              </nav>
            </SheetContent>
          </Sheet>
        </div>
      </div>
      <nav className="hidden" aria-label={mobileNavLabel}>
        {items.map((item) => (
          <span key={item.href}>
            <Link href={item.href}>{item.label}</Link>
            {item.children?.map((child) => (
              <Link key={child.href} href={child.href}>
                {child.label}
              </Link>
            ))}
          </span>
        ))}
        <Link href={cta.href}>{cta.label}</Link>
        {loginHref && <Link href={loginHref}>{loginLabel}</Link>}
      </nav>
    </header>
  )
}

"use client"

import { cn } from "#/lib/utils"

export interface ManageCookiesButtonProps {
  label: string
  manageEvent?: string
  size?: "xs" | "sm"
  className?: string
}

export function ManageCookiesButton({
  label,
  manageEvent = "manage-cookies",
  size = "sm",
  className,
}: ManageCookiesButtonProps) {
  return (
    <button
      type="button"
      onClick={() => window.dispatchEvent(new Event(manageEvent))}
      className={cn(
        size === "xs" ? "text-xs" : "text-sm",
        "text-muted-foreground transition-colors hover:text-primary",
        className,
      )}
    >
      {label}
    </button>
  )
}

import { Image } from "#/components/ui/image"
import { Link } from "#/components/ui/link"
import { Mail, MapPin, Phone, Clock } from "lucide-react"
import { type SocialPlatform, socialIconMap } from "#/components/ui/social-icons"
import { ManageCookiesButton } from "#/components/navigation/manage-cookies-button"
import { cn } from "#/lib/utils"

export interface SocialLink {
  platform: SocialPlatform
  url: string
}

export interface FooterColumn {
  title: string
  links: { label: string; href: string }[]
}

export interface NewsletterProps {
  title: string
  placeholder: string
  buttonLabel: string
  action?: string
}

/**
 * Footer usage recipes:
 *
 * 1. Logo + dark footer (BBX, Soleva, Laveria, Osteoptimum)
 *    brand.logo, variant="dark", colors: { headings: "primary", icons: "primary" }
 *    (requires a --dark token in globals.css; keep "accent" default if
 *    --primary is dark and would blend into the footer background)
 *
 * 2. No logo + tagline (Café des Promeneurs)
 *    brand.name + tagline, hideMonogram: true,
 *    colors: { brandName: "primary" }, className: "bg-secondary/60"
 *
 * 3. Light default (factory-template)
 *    No colors required — headings default to text-primary (readable on
 *    all theme presets). Do NOT default to text-secondary: in shadcn
 *    presets, --secondary is a surface color nearly invisible on light
 *    backgrounds (medical, corporate, hospitality).
 */
export interface FooterProps {
  brand: {
    name: string
    description: string
    tagline?: string
    logo?: string
    initial?: string
    hideMonogram?: boolean
    /** @deprecated Use colors.brandName instead. */
    brandColor?: "primary" | "foreground"
  }
  columns: FooterColumn[]
  contact: {
    title?: string
    address?: string
    phone?: string
    phoneLabel?: string
    email?: string
    mapsUrl?: string
    hours?: string
    hoursLabel?: string
    /** Structured opening hours — days left, hours right, one row each. */
    hoursRows?: { days: string; hours: string }[]
  }
  socials?: SocialLink[]
  legal: {
    links: { label: string; href: string }[]
    copyright: string
  }
  attribution?: { text: string; href: string; logo?: string }
  newsletter?: NewsletterProps
  manageCookiesLabel?: string
  manageCookiesEvent?: string
  variant?: "default" | "dark"
  /** Column headings color. */
  accentColor?: "accent" | "primary" | "secondary" | "foreground"
  /** Contact icon color. */
  iconColor?: "accent" | "primary" | "secondary" | "foreground"
  /** Grouped color overrides (preferred over accentColor/iconColor/brandColor). */
  colors?: {
    headings?: "accent" | "primary" | "secondary" | "foreground"
    icons?: "accent" | "primary" | "secondary" | "foreground"
    brandName?: "primary" | "foreground"
  }
  className?: string
}

export function Footer({
  brand,
  columns,
  contact,
  socials,
  legal,
  attribution,
  newsletter,
  manageCookiesLabel,
  manageCookiesEvent = "manage-cookies",
  variant = "default",
  accentColor,
  iconColor,
  colors,
  className,
}: FooterProps) {
  const dark = variant === "dark"

  const root = dark
    ? "bg-dark text-dark-foreground"
    : "border-t border-border bg-muted/50"

  const colorClass = (color: "accent" | "primary" | "secondary" | "foreground" | undefined) =>
    color === "primary"
      ? "text-primary"
      : color === "secondary"
        ? "text-secondary"
        : color === "foreground"
          ? "text-foreground"
          : dark
            ? "text-accent"
            : "text-primary"

  const headingsColor = colors?.headings ?? accentColor
  const iconsColor = colors?.icons ?? iconColor
  const brandNameColor = colors?.brandName ?? brand.brandColor
  const accentClass = colorClass(headingsColor)

  const brandName =
    brandNameColor === "primary"
      ? "text-primary"
      : dark
        ? "text-dark-foreground"
        : "text-foreground"
  const description = dark ? "text-dark-foreground/70" : "text-muted-foreground"
  const heading = accentClass
  const icon = iconsColor ? colorClass(iconsColor) : accentClass
  const link = dark
    ? "text-dark-foreground/70 transition-colors hover:text-secondary"
    : "text-muted-foreground transition-colors hover:text-primary"
  const socialIcon = dark
    ? "text-dark-foreground/80 transition-colors hover:text-secondary"
    : "text-muted-foreground transition-colors hover:text-primary"
  const bottomBorder = dark ? "border-dark-foreground/10" : "border-border"
  const bottomText = dark ? "text-dark-foreground/60" : "text-muted-foreground"
  const bottomLink = dark
    ? "transition-colors hover:text-secondary"
    : "transition-colors hover:text-primary"

  const inputClass = dark
    ? "border-dark-foreground/20 bg-dark-foreground/10 text-dark-foreground placeholder:text-dark-foreground/50"
    : "border-border bg-background text-foreground placeholder:text-muted-foreground"

  return (
    <footer className={cn(root, className)}>
      <div className="container-premium py-16 md:py-20">
        <div className="grid grid-cols-2 gap-10 lg:grid-cols-4">
          {/* Brand column */}
          <div className="space-y-4">
            <div className="flex items-center gap-2">
              {brand.logo ? (
                <Image
                  src={brand.logo}
                  alt={brand.name}
                  width={160}
                  height={40}
                  unoptimized
                  className="h-10 w-auto rounded-lg object-contain"
                />
              ) : brand.hideMonogram ? null : (
                <span className="flex h-10 w-10 items-center justify-center rounded-full bg-primary text-base font-bold text-primary-foreground">
                  {brand.initial ?? brand.name.charAt(0)}
                </span>
              )}
              <span className={cn("font-heading text-lg font-bold", brandName)}>{brand.name}</span>
            </div>
            {brand.tagline && (
              <p
                className={cn(
                  "text-xs font-medium uppercase tracking-[0.18em]",
                  dark ? "text-dark-foreground/60" : "text-foreground/60",
                )}
              >
                {brand.tagline}
              </p>
            )}
            <p className={cn("text-sm leading-relaxed", description)}>
              {brand.description}
            </p>
            {socials && socials.length > 0 && (
              <div className="flex gap-3 pt-2">
                {socials.map((social) => {
                  const Icon = socialIconMap[social.platform]
                  return (
                    <a
                      key={social.platform}
                      href={social.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className={cn(socialIcon, dark && "flex h-9 w-9 items-center justify-center rounded-full bg-dark-foreground/10")}
                      aria-label={social.platform}
                    >
                      <Icon className="h-5 w-5" />
                    </a>
                  )
                })}
              </div>
            )}
            {newsletter && (
              <form action={newsletter.action} method="post" className="pt-2">
                <h3 className={cn("mb-3 font-heading text-sm font-semibold uppercase tracking-wide", heading)}>
                  {newsletter.title}
                </h3>
                <div className="flex max-w-xs gap-2">
                  <input
                    type="email"
                    name="email"
                    required
                    placeholder={newsletter.placeholder}
                    aria-label={newsletter.placeholder}
                    className={cn(
                      "h-10 min-w-0 flex-1 rounded-lg border px-3 text-sm outline-none transition-colors focus-visible:ring-3 focus-visible:ring-ring/40",
                      inputClass,
                    )}
                  />
                  <button
                    type="submit"
                    className="inline-flex h-10 shrink-0 items-center justify-center rounded-lg bg-primary px-3 text-sm font-semibold text-primary-foreground outline-none transition-colors hover:bg-primary/90 focus-visible:ring-3 focus-visible:ring-primary/40"
                  >
                    {newsletter.buttonLabel}
                  </button>
                </div>
              </form>
            )}
          </div>

          {/* Navigation columns */}
          {columns.map((col) => (
            <div key={col.title}>
              <h3 className={cn("mb-4 font-heading text-sm font-semibold uppercase tracking-wide", heading)}>
                {col.title}
              </h3>
              <ul className="space-y-2.5">
                {col.links.map((linkItem) => (
                  <li key={linkItem.href}>
                    <Link href={linkItem.href} className={cn("text-sm", link)}>
                      {linkItem.label}
                    </Link>
                  </li>
                ))}
              </ul>
            </div>
          ))}

          {/* Contact column */}
          <div>
            <h3 className={cn("mb-4 font-heading text-sm font-semibold uppercase tracking-wide", heading)}>
              {contact.title}
            </h3>
            <ul className="space-y-3">
              {contact.address && (
                <li>
                  {contact.mapsUrl ? (
                    <a
                      href={contact.mapsUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className={cn("flex items-start gap-2 text-sm", link)}
                    >
                      <MapPin className={cn("mt-0.5 h-4 w-4 shrink-0", icon)} aria-hidden="true" />
                      {contact.address}
                    </a>
                  ) : (
                    <span className={cn("flex items-start gap-2 text-sm", description)}>
                      <MapPin className={cn("mt-0.5 h-4 w-4 shrink-0", icon)} aria-hidden="true" />
                      {contact.address}
                    </span>
                  )}
                </li>
              )}
              {contact.phone && (
                <li>
                  <a
                    href={`tel:${contact.phone.replace(/\s/g, "")}`}
                    className={cn("flex items-center gap-2 text-sm", link)}
                  >
                    <Phone className={cn("h-4 w-4 shrink-0", icon)} aria-hidden="true" />
                    {contact.phone}
                    {contact.phoneLabel && (
                      <>
                        <span aria-hidden="true"> · </span>
                        <span className="text-xs font-semibold uppercase text-primary">
                          {contact.phoneLabel}
                        </span>
                      </>
                    )}
                  </a>
                </li>
              )}
              {contact.email && (
                <li>
                  <a
                    href={`mailto:${contact.email}`}
                    className={cn("flex items-center gap-2 text-sm", link)}
                  >
                    <Mail className={cn("h-4 w-4 shrink-0", icon)} aria-hidden="true" />
                    {contact.email}
                  </a>
                </li>
              )}
              {(contact.hours || contact.hoursLabel) && (
                <li>
                  <span className={cn("flex items-start gap-2 text-sm", description)}>
                    <Clock className={cn("mt-0.5 h-4 w-4 shrink-0", icon)} aria-hidden="true" />
                    <span className="whitespace-pre-line">
                      {contact.hoursLabel && (
                        <span className="font-medium">{contact.hoursLabel}</span>
                      )}
                      {contact.hoursLabel && contact.hours && <span> : </span>}
                      {contact.hours && <span>{contact.hours}</span>}
                    </span>
                  </span>
                </li>
              )}
            </ul>
          </div>
        </div>
      </div>

      {/* Bottom bar */}
      <div className={cn("border-t", bottomBorder)}>
        <div className="container-premium flex flex-col gap-6 py-8">
          <div className={cn("flex flex-col items-center justify-between gap-3 text-xs sm:flex-row", bottomText)}>
            <span>{legal.copyright}</span>
            <nav className="flex flex-wrap items-center justify-center gap-x-4 gap-y-1">
              {legal.links.map((linkItem) => (
                <Link
                  key={linkItem.href}
                  href={linkItem.href}
                  className={cn(bottomLink, dark && "text-dark-foreground/70 hover:text-secondary")}
                >
                  {linkItem.label}
                </Link>
              ))}
              {manageCookiesLabel && (
                <ManageCookiesButton
                  label={manageCookiesLabel}
                  manageEvent={manageCookiesEvent}
                  size="xs"
                  className={cn(
                    bottomLink,
                    dark && "text-dark-foreground/70 hover:text-secondary",
                  )}
                />
              )}
            </nav>
          </div>

          {attribution && (
            <div className={cn("flex justify-center text-xs", bottomText)}>
              <a
                href={attribution.href}
                target="_blank"
                rel="noopener noreferrer nofollow"
                className={cn("inline-flex items-center gap-1.5", bottomLink)}
              >
                {attribution.logo && (
                  <Image
                    src={attribution.logo}
                    alt=""
                    width={16}
                    height={16}
                    unoptimized
                    className="h-4 w-4"
                    aria-hidden="true"
                  />
                )}
                {attribution.text}
              </a>
            </div>
          )}
        </div>
      </div>
    </footer>
  )
}

import { HeroAnimation } from "#/components/ui/animations";
import { CtaExternal, CtaLink } from "#/components/ui/cta-button";
import { cn } from "#/lib/utils";
import { Image } from "#/components/ui/image";

export interface HomeHeroProps {
  eyebrow?: string;
  title: string;
  subtitle?: string;
  primaryCta: { label: string; href: string; external?: boolean };
  secondaryCta?: { label: string; href: string; external?: boolean };
  backgroundImage?: string;
  backgroundSrcSet?: string;
  /** Eager + high fetch priority for the background image (default true - full-bleed heroes are usually the LCP). */
  backgroundPriority?: boolean;
  overlayClass?: string;
  className?: string;
}

export function HomeHero({
  eyebrow,
  title,
  subtitle,
  primaryCta,
  secondaryCta,
  backgroundImage,
  backgroundSrcSet,
  backgroundPriority = true,
  overlayClass,
  className,
}: HomeHeroProps) {
  return (
    <section
      className={cn("relative flex min-h-[90vh] items-center", className)}
    >
      {backgroundImage && (
        <Image
          src={backgroundImage}
          alt=""
          fill
          priority={backgroundPriority}
          sizes="100vw"
          srcSet={backgroundSrcSet}
          className="object-cover"
          aria-hidden="true"
        />
      )}
      <div className={cn("absolute inset-0 bg-gradient-to-b from-black/60 via-black/40 to-black/70", overlayClass)} />

